// ─── AI marker 検出 ───────────────────────────────

func TestAIMarker_Detected(t *testing.T) {
	cases := []string{
		"// AI generated",
		"# AI generated (reviewed)",
		"// Generated by Claude",
		"# Generated by Copilot",
		"/* @ai-generated */",
		"// Copilot suggestion",
		"# ChatGPT output",
		"// GPT-4 generated",
	}
	for _, in := range cases {
		if !aiMarkerRe.MatchString(in) {
			t.Errorf("should detect AI marker: %q", in)
		}
	}
}

func TestAIMarker_NotDetected(t *testing.T) {
	cases := []string{
		"// regular comment",
		"# python comment",
		"// generated config file", // "generated" alone shouldn't match
	}
	for _, in := range cases {
		if aiMarkerRe.MatchString(in) {
			t.Errorf("should NOT detect AI marker: %q", in)
		}
	}
}

// ─── AI zone (±10 lines) ─────────────────────────

func TestFindAIZones_MarkerExpandsZone(t *testing.T) {
	lines := []string{
		"line 1",
		"line 2",
		"line 3",
		"// AI generated", // line 4
		"line 5",
		"line 6",
	}
	zones, count := findAIZones(lines)
	if count != 1 {
		t.Errorf("marker count: got %d, want 1", count)
	}
	// ±10 範囲なので全 6 行が zone
	for i := 1; i <= 6; i++ {
		if !zones[i] {
			t.Errorf("line %d should be in AI zone", i)
		}
	}
}

func TestFindAIZones_NoMarker(t *testing.T) {
	lines := []string{"foo", "bar", "baz"}
	zones, count := findAIZones(lines)
	if count != 0 {
		t.Errorf("count: got %d, want 0", count)
	}
	if len(zones) != 0 {
		t.Errorf("zones should be empty")
	}
}

