// ─── AI multiplier ────────────────────────────────

func TestRiskScore_AIZoneMultiplier(t *testing.T) {
	// 同じ CRITICAL violation を、AI zone 内と外で比較
	srcOutsideAI := `db.exec("DROP TABLE users")`
	srcInsideAI := `// AI generated
db.exec("DROP TABLE users")
`
	r1 := Scan(map[string]string{"x.go": srcOutsideAI})
	r2 := Scan(map[string]string{"x.go": srcInsideAI})

	if r2.RiskScore <= r1.RiskScore {
		t.Errorf("AI zone should double risk: outside=%d inside=%d", r1.RiskScore, r2.RiskScore)
	}
	// CRITICAL × 25 = 25, AI で × 2 = 50, さらに ai-marker LOW×2=2 で計 52
	if r2.RiskScore != 50 && r2.RiskScore != 51 && r2.RiskScore != 52 {
		t.Errorf("AI zone score: got %d, expected ~50-52", r2.RiskScore)
	}
}

