// ─── 集計 ────────────────────────────────────────

func TestResult_AggregatesBySeverityAndCategory(t *testing.T) {
	// Split across literals so push-protection scanners don't flag test fixtures.
	src := fmt.Sprintf("// AI generated\ndb.exec(\"DROP TABLE x\")\nkey := \"%s\"\ncookie.secure = false\n",
		"sk_"+"live_AAAAAAAAAAAAAAAAAAAAAAAA")
	r := Scan(map[string]string{"x.go": src})
	if r.BySeverity[RiskCritical] < 2 {
		t.Errorf("should have ≥2 CRITICAL; got %d", r.BySeverity[RiskCritical])
	}
	if r.BySeverity[RiskHigh] < 1 {
		t.Errorf("should have ≥1 HIGH; got %d", r.BySeverity[RiskHigh])
	}
	if r.ByCategory[CategoryData] < 1 {
		t.Errorf("should have data finding")
	}
	if r.ByCategory[CategorySecret] < 1 {
		t.Errorf("should have secret finding")
	}
}

// ─── Cache 統合 ─────────────────────────────────

type fakeCache struct {
	store  map[string][]byte
	hits   int
	misses int
}

func newFakeCache() *fakeCache { return &fakeCache{store: map[string][]byte{}} }
func (f *fakeCache) Get(k string) ([]byte, bool) {
	v, ok := f.store[k]
	if ok {
		f.hits++
		return v, true
	}
	f.misses++
	return nil, false
}
func (f *fakeCache) Set(k string, v []byte) { f.store[k] = v }

func TestScanCached_HitsOnRescan(t *testing.T) {
	cache := newFakeCache()
	files := map[string]string{"x.go": `db.exec("DROP TABLE users")`}

	r1 := ScanCached(files, cache)
	if r1.CacheMisses != 1 {
		t.Errorf("first scan: misses=%d, want 1", r1.CacheMisses)
	}
	r2 := ScanCached(files, cache)
	if r2.CacheHits != 1 {
		t.Errorf("rescan: hits=%d, want 1", r2.CacheHits)
	}
	// findings 同一
	if len(r1.Findings) != len(r2.Findings) {
		t.Errorf("findings should match: %d vs %d", len(r1.Findings), len(r2.Findings))
	}
}

