func TestDetectLanguage(t *testing.T) {
	cases := map[string]string{
		"a.go":   "go",
		"a.ts":   "ts",
		"a.tsx":  "ts",
		"a.js":   "js",
		"a.py":   "python",
		"a.rs":   "rust",
		"a.java": "java",
		"a.cpp":  "c",
		"a.md":   "",
	}
	for path, want := range cases {
		if got := detectLanguage(path); got != want {
			t.Errorf("detectLanguage(%s): got %q, want %q", path, got, want)
		}
	}
}

