// ─── helpers ───────────────────────────────────

func hasRule(fs []Finding, id string) bool {
	for _, f := range fs {
		if f.RuleID == id {
			return true
		}
	}
	return false
}

func findingIDs(fs []Finding) []string {
	out := make([]string, len(fs))
	for i, f := range fs {
		out[i] = f.RuleID
	}
	return out
}

// ─── AnnotateUntested (v0.26 testcoverage 統合) ──────

func TestAnnotateUntested_BumpsScoreForAIWithoutTest(t *testing.T) {
	files := map[string]string{
		"auth.go": "// AI generated\nfunc x() {}",
		"foo.go":  "// not ai\nfunc y() {}",
	}
	res := Scan(files)
	// auth.go は AI 生成、test なし(test map に何もない)
	res2 := AnnotateUntested(res, files, func(p string) bool { return false })
	// AI gen file 1 つで +5
	if res2.RiskScore < res.RiskScore+5 {
		t.Errorf("score should bump by 5: before=%d after=%d", res.RiskScore, res2.RiskScore)
	}
	if len(res2.AIGenWithoutTests) != 1 || res2.AIGenWithoutTests[0] != "auth.go" {
		t.Errorf("untested list: %v", res2.AIGenWithoutTests)
	}
}

func TestAnnotateUntested_SkipFilesWithTest(t *testing.T) {
	files := map[string]string{
		"auth.go": "// AI generated\nfunc x() {}",
	}
	res := Scan(files)
	res2 := AnnotateUntested(res, files, func(p string) bool { return true }) // 全 file test あり
	if len(res2.AIGenWithoutTests) != 0 {
		t.Errorf("with tests: should be empty, got %v", res2.AIGenWithoutTests)
	}
	if res2.RiskScore != res.RiskScore {
		t.Errorf("score should not change: %d vs %d", res.RiskScore, res2.RiskScore)
	}
}

