// ─── Fuzz tests (v0.28) ───────────────────────────────────

// FuzzScan は任意の content を scan して panic しないことを確認。
//
// 期待: malformed input (binary, 巨大行, 特殊正規表現メタ文字, 未終端文字列)
// で ScanText / Scan / AnnotateUntested が panic / 無限ループしない。
// 不変量: risk_score は 0-100 範囲、findings の line ≥ 1。
func FuzzScan(f *testing.F) {
	seeds := []string{
		"",
		// Split across literals so push-protection scanners don't flag test fixtures.
		"// AI generated\\nconst x = \"sk_" + "live_abcdefghijklmnopqrstuvwx\"",
		`db.exec("DROP TABLE users")`,
		strings.Repeat("a", 10000),
		"\x00\x01\x02 binary",
		`md5(password)`,
		"// Generated by Claude\n// Generated by Copilot\n// AI generated\n",
		"\n\n\n\n",
		"[regex meta]{1,3}*?",
	}
	for _, s := range seeds {
		f.Add(s)
	}
	f.Fuzz(func(t *testing.T, content string) {
		// path にも fuzz は当たらないので固定
		res := Scan(map[string]string{"fuzz.go": content})
		// 不変量
		if res.RiskScore < 0 || res.RiskScore > 100 {
			t.Errorf("risk_score out of range: %d", res.RiskScore)
		}
		for _, f := range res.Findings {
			if f.Line < 1 {
				t.Errorf("finding line < 1: %d", f.Line)
			}
		}
		// Summary も panic しないこと
		_ = res.Summary()
	})
}

func TestScanWithRules_UsesCustomRules(t *testing.T) {
	custom := []Rule{
		{
			ID:       "CUSTOM-001",
			Pattern:  regexp.MustCompile(`(?i)DROP\s+TABLE\s+users`),
			Risk:     RiskHigh,
			Category: CategoryData,
		},
	}
	files := map[string]string{"q.go": "// DROP TABLE users\nfunc main() {}"}
	r := ScanWithRules(files, custom)
	if r.FilesScanned != 1 {
		t.Errorf("FilesScanned = %d, want 1", r.FilesScanned)
	}
}

// TestScan_DeterministicOrder_SamePositionCollision is the integration-level
// fence for the determinism invariant: Scan ranges the input files map (Go
// randomizes map iteration), so its public output must still be byte-stable
// across runs. Two rules matching the same token produce findings at the same
// File/Line/Column differing only by RuleID — the collision that exposed the
// non-total-order sort. Running many times catches any reintroduced
// map-order-dependent ordering (e.g. a future unsorted map-range).
func TestScan_DeterministicOrder_SamePositionCollision(t *testing.T) {
	rules := []Rule{
		{ID: "z-rule", Pattern: regexp.MustCompile(`SECRET`), Category: CategoryData, Risk: RiskHigh, Message: "z"},
		{ID: "a-rule", Pattern: regexp.MustCompile(`SECRET`), Category: CategoryData, Risk: RiskHigh, Message: "a"},
	}
	files := map[string]string{}
	for i := 0; i < 20; i++ {
		files[fmt.Sprintf("f%02d.go", i)] = "x := SECRET\n"
	}
	sig := func(r Result) string {
		var sb strings.Builder
		for _, f := range r.Findings {
			fmt.Fprintf(&sb, "%s:%d:%d:%s\n", f.File, f.Line, f.Column, f.RuleID)
		}
		return sb.String()
	}
	want := sig(ScanWithRules(files, rules))
	if want == "" {
		t.Fatal("expected findings from colliding rules, got none")
	}
	for run := 0; run < 40; run++ {
		if got := sig(ScanWithRules(files, rules)); got != want {
			t.Fatalf("run %d: non-deterministic Scan order over map input\nwant:\n%s\ngot:\n%s", run, want, got)
		}
	}
}
